import { FixedClock } from '@/shared-kernel';
import { Invoice, InvoiceSource } from '../domain/invoice';
import { SourceAlreadyInvoicedError } from '../domain/invoice.errors';
import { InvoiceRepository } from '../domain/invoice.repository';
import { PriceList } from '../domain/price-list';
import { InvoicingService } from './invoicing.service';

class InMemoryInvoiceRepository extends InvoiceRepository {
  readonly items: Invoice[] = [];

  async existsForSource(source: InvoiceSource) {
    return (await this.findBySource(source)) !== null;
  }

  async findByPayer(payerId: string) {
    return this.items.filter((i) => i.toSnapshot().payerId === payerId);
  }

  async findBySource(source: InvoiceSource) {
    return (
      this.items.find((i) => {
        const s = i.toSnapshot().source;
        return s.type === source.type && s.id === source.id;
      }) ?? null
    );
  }

  async save(invoice: Invoice) {
    this.items.push(invoice);
  }
}

describe('InvoicingService', () => {
  let repository: InMemoryInvoiceRepository;
  let service: InvoicingService;

  beforeEach(() => {
    repository = new InMemoryInvoiceRepository();
    service = new InvoicingService(repository, new PriceList(), new FixedClock(new Date('2026-03-02T11:00:00Z')));
  });

  it('prices the procedure codes of an encounter into a persisted invoice', async () => {
    await service.invoiceEncounter({ encounterId: 'e-1', payerId: 'person-1', procedureCodes: ['10101012'] });

    expect(repository.items).toHaveLength(1);
    expect(repository.items[0].toSnapshot()).toMatchObject({
      payerId: 'person-1',
      source: { type: 'ENCOUNTER', id: 'e-1' },
      lines: [{ code: '10101012', amountCents: 25_000 }],
    });
  });

  it('never invoices the same encounter twice', async () => {
    const input = { encounterId: 'e-1', payerId: 'person-1', procedureCodes: ['10101012'] };
    await service.invoiceEncounter(input);

    await expect(service.invoiceEncounter(input)).rejects.toThrow(SourceAlreadyInvoicedError);
    expect(repository.items).toHaveLength(1);
  });

  it('charges the no-show fee once per appointment', async () => {
    await service.chargeNoShow({ appointmentId: 'appt-1', payerId: 'person-1' });

    await expect(service.chargeNoShow({ appointmentId: 'appt-1', payerId: 'person-1' })).rejects.toThrow(
      SourceAlreadyInvoicedError,
    );
    expect(repository.items[0].totalCents).toBe(10_000);
  });
});
import { Injectable } from '@nestjs/common';
import { Clock, newId, PersonId } from '@/shared-kernel';
import { Invoice, InvoiceLine, InvoiceSource } from '../domain/invoice';
import { SourceAlreadyInvoicedError } from '../domain/invoice.errors';
import { InvoiceRepository } from '../domain/invoice.repository';
import { PriceList } from '../domain/price-list';

@Injectable()
export class InvoicingService {
  constructor(
    private readonly invoices: InvoiceRepository,
    private readonly priceList: PriceList,
    private readonly clock: Clock,
  ) {}

  async invoiceEncounter(input: { encounterId: string; payerId: PersonId; procedureCodes: string[] }): Promise<Invoice> {
    return this.issue(
      input.payerId,
      { type: 'ENCOUNTER', id: input.encounterId },
      this.priceList.linesFor(input.procedureCodes),
    );
  }

  async chargeNoShow(input: { appointmentId: string; payerId: PersonId }): Promise<Invoice> {
    return this.issue(input.payerId, { type: 'NO_SHOW', id: input.appointmentId }, [this.priceList.noShowFee()]);
  }

  async invoicesOf(payerId: PersonId): Promise<Invoice[]> {
    return this.invoices.findByPayer(payerId);
  }

  async invoiceFor(source: InvoiceSource): Promise<Invoice | null> {
    return this.invoices.findBySource(source);
  }

  private async issue(payerId: PersonId, source: InvoiceSource, lines: InvoiceLine[]): Promise<Invoice> {
    if (await this.invoices.existsForSource(source)) {
      throw new SourceAlreadyInvoicedError(source.type, source.id);
    }
    const invoice = Invoice.issue({ id: newId(), payerId, source, lines, issuedAt: this.clock.now() });
    await this.invoices.save(invoice);
    return invoice;
  }
}
import { DomainError } from '@/shared-kernel';

export class EmptyInvoiceError extends DomainError {
  constructor() {
    super('An invoice needs at least one line');
  }
}

export class InvalidLineAmountError extends DomainError {
  constructor(code: string) {
    super(`Line ${code} must have a positive amount`);
  }
}

export class UnknownProcedureError extends DomainError {
  constructor(code: string) {
    super(`No price for procedure ${code}`);
  }
}

export class SourceAlreadyInvoicedError extends DomainError {
  constructor(sourceType: string, sourceId: string) {
    super(`${sourceType} ${sourceId} has already been invoiced`);
  }
}
import type { Invoice, InvoiceSource } from './invoice';

export abstract class InvoiceRepository {
  abstract existsForSource(source: InvoiceSource): Promise<boolean>;
  abstract findByPayer(payerId: string): Promise<Invoice[]>;
  abstract findBySource(source: InvoiceSource): Promise<Invoice | null>;
  abstract save(invoice: Invoice): Promise<void>;
}
import { Invoice } from './invoice';
import { EmptyInvoiceError, InvalidLineAmountError, UnknownProcedureError } from './invoice.errors';
import { PriceList } from './price-list';

const base = {
  id: 'inv-1',
  payerId: 'person-1',
  source: { type: 'ENCOUNTER' as const, id: 'e-1' },
  issuedAt: new Date('2026-03-02T11:00:00Z'),
};

describe('Invoice', () => {
  it('totals its lines', () => {
    const invoice = Invoice.issue({
      ...base,
      lines: new PriceList().linesFor(['10101012', '40304361']),
    });

    expect(invoice.totalCents).toBe(28_500);
  });

  it('cannot be issued without lines', () => {
    expect(() => Invoice.issue({ ...base, lines: [] })).toThrow(EmptyInvoiceError);
  });

  it('rejects non-positive or fractional amounts', () => {
    expect(() => Invoice.issue({ ...base, lines: [{ code: 'X', description: 'x', amountCents: 0 }] })).toThrow(
      InvalidLineAmountError,
    );
    expect(() => Invoice.issue({ ...base, lines: [{ code: 'X', description: 'x', amountCents: 10.5 }] })).toThrow(
      InvalidLineAmountError,
    );
  });
});

describe('PriceList', () => {
  it('refuses to price an unknown procedure', () => {
    expect(() => new PriceList().linesFor(['99999999'])).toThrow(UnknownProcedureError);
  });
});
import type { PersonId } from '@/shared-kernel';
import { EmptyInvoiceError, InvalidLineAmountError } from './invoice.errors';

export type InvoiceSourceType = 'ENCOUNTER' | 'NO_SHOW';
export type InvoiceStatus = 'OPEN';

export interface InvoiceSource {
  type: InvoiceSourceType;
  id: string;
}

export interface InvoiceLine {
  code: string;
  description: string;
  amountCents: number;
}

export interface InvoiceSnapshot {
  id: string;
  payerId: PersonId;
  source: InvoiceSource;
  status: InvoiceStatus;
  lines: InvoiceLine[];
  issuedAt: Date;
}

export interface IssueInvoiceInput {
  id: string;
  payerId: PersonId;
  source: InvoiceSource;
  lines: InvoiceLine[];
  issuedAt: Date;
}

export class Invoice {
  private constructor(private readonly props: InvoiceSnapshot) {}

  static issue(input: IssueInvoiceInput): Invoice {
    if (input.lines.length === 0) {
      throw new EmptyInvoiceError();
    }
    for (const line of input.lines) {
      if (!Number.isInteger(line.amountCents) || line.amountCents <= 0) {
        throw new InvalidLineAmountError(line.code);
      }
    }
    return new Invoice({ ...input, lines: input.lines.map((l) => ({ ...l })), status: 'OPEN' });
  }

  static restore(snapshot: InvoiceSnapshot): Invoice {
    return new Invoice({ ...snapshot });
  }

  get id(): string {
    return this.props.id;
  }

  get totalCents(): number {
    return this.props.lines.reduce((sum, line) => sum + line.amountCents, 0);
  }

  toSnapshot(): InvoiceSnapshot {
    return { ...this.props, source: { ...this.props.source }, lines: this.props.lines.map((l) => ({ ...l })) };
  }
}
import type { InvoiceLine } from './invoice';
import { UnknownProcedureError } from './invoice.errors';

interface PriceEntry {
  description: string;
  amountCents: number;
}

export const NO_SHOW_FEE_CODE = 'NO-SHOW';

const DEFAULT_PRICES: Record<string, PriceEntry> = {
  '10101012': { description: 'Office consultation', amountCents: 25_000 },
  '40304361': { description: 'Complete blood count', amountCents: 3_500 },
  '40101010': { description: 'Electrocardiogram', amountCents: 8_000 },
  [NO_SHOW_FEE_CODE]: { description: 'No-show fee', amountCents: 10_000 },
};

export class PriceList {
  constructor(private readonly prices: Readonly<Record<string, PriceEntry>> = DEFAULT_PRICES) {}

  linesFor(codes: readonly string[]): InvoiceLine[] {
    return codes.map((code) => {
      const entry = this.prices[code];
      if (!entry) {
        throw new UnknownProcedureError(code);
      }
      return { code, ...entry };
    });
  }

  noShowFee(): InvoiceLine {
    return this.linesFor([NO_SHOW_FEE_CODE])[0];
  }
}
import { Injectable } from '@nestjs/common';
import type { BillingInvoice, BillingInvoiceLine } from '@prisma/client';
import { newId } from '@/shared-kernel';
import { PrismaService } from '@/infrastructure/prisma/prisma.service';
import { Invoice, InvoiceSource, InvoiceSourceType, InvoiceStatus } from '../domain/invoice';
import { InvoiceRepository } from '../domain/invoice.repository';

@Injectable()
export class PrismaInvoiceRepository extends InvoiceRepository {
  constructor(private readonly prisma: PrismaService) {
    super();
  }

  async existsForSource(source: InvoiceSource): Promise<boolean> {
    const count = await this.prisma.billingInvoice.count({
      where: { sourceType: source.type, sourceId: source.id },
    });
    return count > 0;
  }

  async findByPayer(payerId: string): Promise<Invoice[]> {
    const rows = await this.prisma.billingInvoice.findMany({
      where: { payerId },
      include: { lines: true },
      orderBy: { issuedAt: 'asc' },
    });
    return rows.map(toDomain);
  }

  async findBySource(source: InvoiceSource): Promise<Invoice | null> {
    const row = await this.prisma.billingInvoice.findUnique({
      where: { sourceType_sourceId: { sourceType: source.type, sourceId: source.id } },
      include: { lines: true },
    });
    return row ? toDomain(row) : null;
  }

  async save(invoice: Invoice): Promise<void> {
    const s = invoice.toSnapshot();
    await this.prisma.billingInvoice.create({
      data: {
        id: s.id,
        payerId: s.payerId,
        sourceType: s.source.type,
        sourceId: s.source.id,
        status: s.status,
        totalCents: invoice.totalCents,
        issuedAt: s.issuedAt,
        lines: { create: s.lines.map((line) => ({ id: newId(), ...line })) },
      },
    });
  }
}

function toDomain(row: BillingInvoice & { lines: BillingInvoiceLine[] }): Invoice {
  return Invoice.restore({
    id: row.id,
    payerId: row.payerId,
    source: { type: row.sourceType as InvoiceSourceType, id: row.sourceId },
    status: row.status as InvoiceStatus,
    issuedAt: row.issuedAt,
    lines: row.lines.map(({ code, description, amountCents }) => ({ code, description, amountCents })),
  });
}
import { Module } from '@nestjs/common';
import { ClinicalEventsListener } from './api/clinical-events.listener';
import { InvoicesController } from './api/invoices.controller';
import { SchedulingEventsListener } from './api/scheduling-events.listener';
import { InvoicingService } from './application/invoicing.service';
import { InvoiceRepository } from './domain/invoice.repository';
import { PriceList } from './domain/price-list';
import { PrismaInvoiceRepository } from './infrastructure/prisma-invoice.repository';

@Module({
