import type { PersonId } from '@/shared-kernel';
import { EmptyInvoiceError, InvalidLineAmountError } from './invoice.errors';

export type InvoiceSourceType = 'ENCOUNTER' | 'NO_SHOW';
export type InvoiceStatus = 'OPEN';

export interface InvoiceSource {
  type: InvoiceSourceType;
  id: string;
}

export interface InvoiceLine {
  code: string;
  description: string;
  amountCents: number;
}

export interface InvoiceSnapshot {
  id: string;
  payerId: PersonId;
  source: InvoiceSource;
  status: InvoiceStatus;
  lines: InvoiceLine[];
  issuedAt: Date;
}

export interface IssueInvoiceInput {
  id: string;
  payerId: PersonId;
  source: InvoiceSource;
  lines: InvoiceLine[];
  issuedAt: Date;
}

export class Invoice {
  private constructor(private readonly props: InvoiceSnapshot) {}

  static issue(input: IssueInvoiceInput): Invoice {
    if (input.lines.length === 0) {
      throw new EmptyInvoiceError();
    }
    for (const line of input.lines) {
      if (!Number.isInteger(line.amountCents) || line.amountCents <= 0) {
        throw new InvalidLineAmountError(line.code);
      }
    }
    return new Invoice({ ...input, lines: input.lines.map((l) => ({ ...l })), status: 'OPEN' });
  }

  static restore(snapshot: InvoiceSnapshot): Invoice {
    return new Invoice({ ...snapshot });
  }

  get id(): string {
    return this.props.id;
  }

  get totalCents(): number {
    return this.props.lines.reduce((sum, line) => sum + line.amountCents, 0);
  }

  toSnapshot(): InvoiceSnapshot {
    return { ...this.props, source: { ...this.props.source }, lines: this.props.lines.map((l) => ({ ...l })) };
  }
}
import type { InvoiceLine } from './invoice';
import { UnknownProcedureError } from './invoice.errors';

interface PriceEntry {
  description: string;
  amountCents: number;
}

export const NO_SHOW_FEE_CODE = 'NO-SHOW';

const DEFAULT_PRICES: Record<string, PriceEntry> = {
  '10101012': { description: 'Office consultation', amountCents: 25_000 },
  '40304361': { description: 'Complete blood count', amountCents: 3_500 },
  '40101010': { description: 'Electrocardiogram', amountCents: 8_000 },
  [NO_SHOW_FEE_CODE]: { description: 'No-show fee', amountCents: 10_000 },
};

export class PriceList {
  constructor(private readonly prices: Readonly<Record<string, PriceEntry>> = DEFAULT_PRICES) {}

  linesFor(codes: readonly string[]): InvoiceLine[] {
    return codes.map((code) => {
      const entry = this.prices[code];
      if (!entry) {
        throw new UnknownProcedureError(code);
      }
      return { code, ...entry };
    });
  }

  noShowFee(): InvoiceLine {
    return this.linesFor([NO_SHOW_FEE_CODE])[0];
  }
}
